<?php
function progress_db() { $db = new PDO("sqlite:" . __DIR__ . "/learnquest.db"); $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION); $db->exec("CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, child_id TEXT, subject TEXT, skill TEXT, is_correct INTEGER, response_time REAL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)"); return $db; } function log_attempt($subject, $skill, $is_correct, $seconds) { try { $st = progress_db()->prepare("INSERT INTO attempts (child_id, subject, skill, is_correct, response_time) VALUES (?, ?, ?, ?, ?)"); $st->execute([(string)($_SESSION["child_id"] ?? "1"), $subject, $skill, $is_correct ? 1 : 0, round(min($seconds, 120), 1)]); } catch (Exception $e) { } }
function get_progress_report($child_id = null) { $report = []; try { $st = progress_db()->prepare("SELECT subject, skill, COUNT(*) AS total, AVG(is_correct) AS accuracy, AVG(response_time) AS avg_time FROM attempts WHERE child_id = ? GROUP BY subject, skill"); $st->execute([(string)($child_id ?? $_SESSION["child_id"] ?? "1")]); foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $row) { $payload = json_encode(["subject" => $row["subject"], "skill_node" => $row["skill"], "accuracy_rate" => (float)$row["accuracy"], "avg_response_time" => (float)$row["avg_time"], "total_questions" => (int)$row["total"]]); $ch = curl_init("http://127.0.0.1:8000/api/feedback/generate"); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true, CURLOPT_POSTFIELDS => $payload, CURLOPT_HTTPHEADER => ["Content-Type: application/json"], CURLOPT_CONNECTTIMEOUT => 2, CURLOPT_TIMEOUT => 5]); $resp = curl_exec($ch); curl_close($ch); $fb = $resp ? json_decode($resp, true) : null; $report[] = ["subject" => $row["subject"], "skill" => $row["skill"], "total" => (int)$row["total"], "accuracy" => round($row["accuracy"] * 100), "status" => $fb["status"] ?? "neutral", "summary" => $fb["summary"] ?? "Feedback is unavailable right now.", "action" => $fb["action_item"] ?? ""]; } } catch (Exception $e) { } return $report; }
function get_family_report($pdo, $parent_id) { $family = []; $st = $pdo->prepare("SELECT id, name, surname, age, grade FROM children WHERE parent_id = ? ORDER BY name"); $st->execute([$parent_id]); foreach ($st->fetchAll() as $ch) { $ch["report"] = get_progress_report((string) $ch["id"]); $family[] = $ch; } return $family; }
